          "type": "text",
          "text": "def transform(g):\n    # Retain the solid rectangular objects; discard sparse colored noise and\n    # restore their original fill colors where small marker pixels interrupted them.\n    from collections import deque, Counter\n    h, w = len(g), len(g[0])\n    bg = Counter(v for row in g for v in row).most_common(1)[0][0]\n    out = [[bg] * w for _ in range(h)]\n    seen = set()\n    for y in range(h):\n        for x in range(w):\n            c = g[y][x]\n            if c == bg or (y, x) in seen:\n                continue\n            q = deque([(y, x)])\n            seen.add((y, x))\n            pts = []\n            while q:\n                a, b = q.popleft()\n                pts.append((a, b))\n                for da in (-1, 0, 1):\n                    for db in (-1, 0, 1):\n                        aa, bb = a + da, b + db\n                        if (da or db) and 0 <= aa < h and 0 <= bb < w and (aa, bb) not in seen and g[aa][bb] == c:\n                            seen.add((aa, bb))\n                            q.append((aa, bb))\n            ys = [a for a, _ in pts]\n            xs = [b for _, b in pts]\n            top, bottom, left, right = min(ys), max(ys), min(xs), max(xs)\n            area = (bottom - top + 1) * (right - left + 1)\n            if area >= 4 and len(pts) / area >= 0.65:\n                for a in range(top, bottom + 1):\n                    for b in range(left, right + 1):\n                        out[a][b] = c\n    return out\n"
        }
