def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Extend each diagonal adjacent pair of matching non-background cells
    # through the background in both directions.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    y, x = r - dr, c - dc
                    while 0 <= y < h and 0 <= x < w and grid[y][x] == background:
                        out[y][x] = color
                        y -= dr
                        x -= dc
                    y, x = rr + dr, cc + dc
                    while 0 <= y < h and 0 <= x < w and grid[y][x] == background:
                        out[y][x] = color
                        y += dr
                        x += dc
    return out
