def transform(grid):
    # A lone diagonal apex with two outward/downward diagonal arms bounds
    # a triangular region; fill its interior with color 2.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            # Candidate apexes occur above this cell; test whether this cell
            # lies between the two diagonals descending from that apex.
            for a in range(r):
                d = r - a
                for apex in range(w):
                    if grid[a][apex] != 3:
                        continue
                    left, right = apex - d, apex + d
                    if 0 <= left < w and 0 <= right < w:
                        if grid[r][left] == 3 and grid[r][right] == 3 and left < c < right:
                            out[r][c] = 2
                            break
                if out[r][c] == 2:
                    break
    return out
PY
